// Company avatars that employees and admins can choose as a profile picture.
// The artwork lives in portal/public/avatars (generated by
// portal/scripts/generate-avatars.mjs). Keep this list in sync with it.

export const AVATAR_CATALOG = [
  { id: "avatar-01", label: "Crimson" },
  { id: "avatar-02", label: "Ember" },
  { id: "avatar-03", label: "Sunrise" },
  { id: "avatar-04", label: "Amber" },
  { id: "avatar-05", label: "Forest" },
  { id: "avatar-06", label: "Mint" },
  { id: "avatar-07", label: "Lagoon" },
  { id: "avatar-08", label: "Sky" },
  { id: "avatar-09", label: "Indigo" },
  { id: "avatar-10", label: "Violet" },
  { id: "avatar-11", label: "Orchid" },
  { id: "avatar-12", label: "Slate" },
];

export const avatarPathFor = (id) => `/avatars/${id}.svg`;

export const AVATAR_PATHS = AVATAR_CATALOG.map((item) =>
  avatarPathFor(item.id)
);

export const isPresetAvatarPath = (value) =>
  typeof value === "string" && AVATAR_PATHS.includes(value.trim());